# Gzips page/index.html into src/page.h (generated, not in git) before each build.
import gzip
import os
Import("env")  # noqa: F821  (provided by PlatformIO)

root = env.subst("$PROJECT_DIR")  # noqa: F821
src = os.path.join(root, "page", "index.html")
dst = os.path.join(root, "src", "page.h")

with open(src, "rb") as f:
    data = gzip.compress(f.read(), compresslevel=9, mtime=0)

lines = ", ".join(str(b) for b in data)
body = (
    "// Generated by scripts/embed_page.py from page/index.html. Do not edit.\n"
    "#pragma once\n#include <stdint.h>\n"
    f"static const uint8_t kPageGz[{len(data)}] = {{{lines}}};\n"
)
old = open(dst).read() if os.path.exists(dst) else ""
if old != body:
    with open(dst, "w") as f:
        f.write(body)
print(f"Embedded page/index.html: {len(data)} bytes gzipped")
